mapper.select:
SELECT id,task_uuid,user_id,expected_revision,status,attempt_count,max_attempts,
  next_attempt_at,worker_job_uuid,worker_outcome,lease_token,lease_until,updated_at
FROM torrent_native_retry_plan WHERE user_id=#{owner} AND task_uuid=#{taskUuid}

SELECT id,task_uuid,user_id,expected_revision,status,attempt_count,max_attempts,
  next_attempt_at,worker_job_uuid,worker_outcome,lease_token,lease_until,updated_at
FROM torrent_native_retry_plan
WHERE status='PENDING' AND next_attempt_at <= #{now}
  AND attempt_count < max_attempts
ORDER BY next_attempt_at ASC,id ASC LIMIT #{limit}

mapper.update:
UPDATE torrent_native_retry_plan SET status='CLAIMED',lease_token=#{token},
  lease_until=#{until},attempt_count=attempt_count+1,updated_at=#{now}
WHERE user_id=#{owner} AND task_uuid=#{taskUuid} AND expected_revision=#{expectedRevision}
  AND status='PENDING' AND next_attempt_at <= #{now}
  AND attempt_count < max_attempts

UPDATE torrent_native_retry_plan SET worker_job_uuid=#{jobUuid}
WHERE user_id=#{owner} AND task_uuid=#{taskUuid} AND expected_revision=#{revision}
  AND status='CLAIMED' AND lease_token=#{token} AND worker_job_uuid IS NULL
  AND lease_until > #{now}

UPDATE torrent_native_retry_plan
SET status=CASE WHEN attempt_count >= max_attempts THEN 'STOPPED' ELSE 'PENDING' END,
    lease_token=NULL,lease_until=NULL,next_attempt_at=#{next},updated_at=#{now}
WHERE user_id=#{owner} AND task_uuid=#{taskUuid} AND expected_revision=#{revision}
  AND status='CLAIMED' AND lease_token=#{token} AND worker_job_uuid IS NULL

UPDATE torrent_native_retry_plan SET status='STOPPED',worker_outcome=#{outcome},
  lease_token=NULL,lease_until=NULL,updated_at=#{now}
WHERE user_id=#{owner} AND task_uuid=#{taskUuid} AND expected_revision=#{revision}
  AND status='CLAIMED' AND lease_token=#{token} AND worker_job_uuid=#{jobUuid}
  AND worker_outcome IS NULL

UPDATE torrent_native_retry_plan SET status='STOPPED',lease_token=NULL,lease_until=NULL
WHERE user_id=#{owner} AND task_uuid=#{taskUuid} AND expected_revision=#{revision}
  AND status='CLAIMED' AND lease_token=#{token}

